export function solve(left: number[], right: number[]): number[] {
  const merged: number[] = [];
  const leftIterator = left.values();
  const rightIterator = right.values();
  let l = leftIterator.next();
  let r = rightIterator.next();
  while (!l.done && !r.done) {
    if (l.value <= r.value) {
      merged.push(l.value);
      l = leftIterator.next();
    } else {
      merged.push(r.value);
      r = rightIterator.next();
    }
  }
  while (!l.done) {
    merged.push(l.value);
    l = leftIterator.next();
  }
  while (!r.done) {
    merged.push(r.value);
    r = rightIterator.next();
  }
  return merged;
}

